// ─── File: LatestDemo.java ───
// Latest-row-per-group: unstable (timestamp only) vs deterministic (timestamp + id).
package com.bank.latest;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;
import java.util.stream.*;

public class LatestDemo {
    private static final Logger log = Logger.getLogger(LatestDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TxnRepository repo = new TxnRepository();
        LatestTxnService service = new LatestTxnService(repo);

        log.info("=== UNSTABLE: order by timestamp only (tie → arbitrary) ===");
        for (int run = 1; run <= 3; run++) {
            int r = run;
            Map<String, Txn> latest = service.latestPerAccountUnstable();
            latest.forEach((acct, t) -> log.warning(() ->
                "run" + r + " " + acct + " latest=" + t.txnId + " (may differ per run!)"));
        }

        log.info("=== DETERMINISTIC: order by timestamp DESC, txn_id DESC ===");
        for (int run = 1; run <= 3; run++) {
            int r = run;
            Map<String, Txn> latest = service.latestPerAccountDeterministic();
            latest.forEach((acct, t) -> log.info(() ->
                "run" + r + " " + acct + " latest=" + t.txnId + " (same every run)"));
        }
    }
}

// ─── Would be in model/Txn.java ───
class Txn {
    final String txnId, accountId, createdAt; final BigDecimal amount;
    Txn(String id, String acct, BigDecimal amt, String at) {
        this.txnId = id; this.accountId = acct; this.amount = amt; this.createdAt = at;
    }
}

// ─── Would be in repository/TxnRepository.java ───
class TxnRepository {
    List<Txn> findAll() {
        return List.of(
            new Txn("T1", "SAV2001", new BigDecimal("10000"), "2026-10-25 10:00:00"),
            new Txn("T2", "SAV2001", new BigDecimal("20000"), "2026-10-25 12:00:00"),
            new Txn("T3", "SAV2001", new BigDecimal("30000"), "2026-10-25 12:00:00"));
    }
}

// ─── Would be in service/LatestTxnService.java ───
class LatestTxnService {
    private final TxnRepository repo;
    LatestTxnService(TxnRepository repo) { this.repo = repo; }

    // UNSTABLE: order by timestamp only; simulate arbitrary tie resolution by shuffling.
    Map<String, Txn> latestPerAccountUnstable() {
        List<Txn> rows = new ArrayList<>(repo.findAll());
        Collections.shuffle(rows); // mimics unspecified physical order / plan changes
        Map<String, Txn> latest = new LinkedHashMap<>();
        for (Txn t : rows) {
            latest.merge(t.accountId, t, (cur, cand) ->
                cand.createdAt.compareTo(cur.createdAt) > 0 ? cand : cur); // ties: keep first seen
        }
        return latest;
    }

    // DETERMINISTIC: order by timestamp DESC, then txn_id DESC as unique tie-breaker.
    Map<String, Txn> latestPerAccountDeterministic() {
        return repo.findAll().stream()
            .collect(Collectors.groupingBy(t -> t.accountId, LinkedHashMap::new,
                Collectors.collectingAndThen(Collectors.toList(), list ->
                    list.stream().max(
                        Comparator.comparing((Txn t) -> t.createdAt)
                                  .thenComparing(t -> t.txnId)   // unique tie-breaker
                    ).orElseThrow())));
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
